export function detail(row){return {...row,active:true,postingUrl:'https://jobs.smartrecruiters.com/PortmanDentex/'+row.id+'-fictional-dentist',jobAd:{sections:{companyDescription:{title:'Company description',text:'<p>Fictional test practice.</p>'},jobDescription:{title:'Job description',text:'<p>Visa sponsorship available.</p><p>GDC registration and Northern Ireland Dental List registration required.</p>'},qualifications:{title:'Qualifications',text:''},additionalInformation:{title:'Additional information',text:'<p>Fictional terms for isolated tests only.</p>'}}}};}
export function provider(rows,hook){const calls=[];const fetcher=async(url,options)=>{calls.push(String(url));const u=new URL(url);if(u.origin!=='https://api.smartrecruiters.com'||!u.pathname.startsWith('/v1/companies/PortmanDentex/postings'))throw Error('Unapproved fixture destination');let value;if(u.search){const offset=Number(u.searchParams.get('offset'));value={offset,limit:100,totalFound:rows.length,content:rows.slice(offset,offset+100)};}else{const row=rows.find(r=>r.id===u.pathname.split('/').at(-1));if(!row)return new Response('',{status:404});value=detail(row);}const altered=hook?.(value,u,options,calls.length);return altered instanceof Response?altered:Response.json(altered??value);};return {fetcher,calls};}
